// Clear cache for testing
const stored = $getWorkflowStaticData('global');
stored.reviewedPrIds = [];

const prs = $input.all();
let reviewedIds = [];

const allPRs = [];

// Handle all possible GitHub response formats
for (const item of prs) {
  const data = item.json;
  if (!data) continue;

  // Format 1: direct PR object
  if (data.number && data.html_url) {
    allPRs.push(data);
    continue;
  }

  // Format 2: wrapped {0: pr1, 1: pr2, ...}
  for (const val of Object.values(data)) {
    if (val && typeof val === 'object' && val.number && val.html_url) {
      allPRs.push(val);
    }
  }
}

// Deduplicate by PR number
const seen = new Set();
const uniquePRs = allPRs.filter(pr => {
  if (seen.has(pr.number)) return false;
  seen.add(pr.number);
  return true;
});

console.log('Unique PRs found:', uniquePRs.map(p => p.number));

if (uniquePRs.length === 0) {
  return [{ json: { hasNewPRs: false, reviewedIds, message: 'No open PRs' } }];
}

return uniquePRs.map(pr => ({
  json: {
    hasNewPRs: true,
    number: pr.number,
    title: pr.title || 'No title',
    author: pr.user ? pr.user.login : 'unknown',
    branch: pr.head ? pr.head.ref : 'unknown',
    baseBranch: pr.base ? pr.base.ref : 'main',
    url: pr.html_url || '',
    createdAt: pr.created_at || '',
    filesChanged: pr.changed_files || 0,
    additions: pr.additions || 0,
    deletions: pr.deletions || 0,
    body: pr.body ? pr.body.substring(0, 300) : 'No description',
    reviewedIds
  }
}));

const allItems = $input.all();

// Separate PR metadata items from file diff items
// PR metadata items have 'number' and 'hasNewPRs' fields
// File diff items have 'filename' field

let prData = null;
const files = [];

for (const item of allItems) {
  const d = item.json;
  if (!d) continue;

  // File diff item - has filename
  if (d.filename) {
    files.push({
      filename: d.filename,
      status: d.status || 'modified',
      additions: d.additions || 0,
      deletions: d.deletions || 0,
      patch: d.patch ? d.patch.substring(0, 800) : 'No diff'
    });
    continue;
  }

  // Wrapped file objects {0: file1, 1: file2}
  let foundFiles = false;
  for (const val of Object.values(d)) {
    if (val && typeof val === 'object' && val.filename) {
      files.push({
        filename: val.filename,
        status: val.status || 'modified',
        additions: val.additions || 0,
        deletions: val.deletions || 0,
        patch: val.patch ? val.patch.substring(0, 800) : 'No diff'
      });
      foundFiles = true;
    }
  }
  if (foundFiles) continue;

  // PR metadata item
  if (d.number && d.hasNewPRs !== undefined) {
    prData = d;
  }
}

// Fallback: try getting PR data from the Loop node context
if (!prData) {
  try {
    prData = $node['🔁 Loop Over PRs'].json;
  } catch(e) {
    console.log('Could not get PR from Loop node:', e.message);
  }
}

console.log('PR number:', prData ? prData.number : 'NOT FOUND');
console.log('Files found:', files.length);

const filesSummary = files.map(f =>
  f.filename + ' (' + f.status + ', +' + f.additions + '/-' + f.deletions + ')'
).join(', ');

const diffText = files.slice(0, 3).map(f =>
  '--- ' + f.filename + ' ---\n' + f.patch
).join('\n\n');

const promptLines = [
  'Review this GitHub pull request and respond ONLY in this format:',
  'SEVERITY: [CRITICAL or NORMAL]',
  'SCORE: [1-10]',
  'SUMMARY: [one sentence]',
  'ISSUES: [concerns or NONE]',
  'SUGGESTIONS: [one actionable fix]',
  '',
  'PR #' + prData.number + ': ' + prData.title,
  'Author: ' + prData.author,
  'Branch: ' + prData.branch + ' into ' + prData.baseBranch,
  'Description: ' + prData.body,
  'Files: ' + (filesSummary || 'none'),
  '',
  'Code changes:',
  diffText || 'No diff available',
  '',
  'Mark CRITICAL if: hardcoded secrets, passwords, auth bypass, security vulnerabilities.',
  'Mark NORMAL for: features, bug fixes, refactoring, docs.'
];

return [{ json: {
  pr: prData,
  files,
  prompt: promptLines.join('\n'),
  reviewedIds: prData.reviewedIds || []
} }];

