const item = $input.first().json;
const rawContent = item.choices[0].message.content;

function extractField(text, field) {
  const regex = new RegExp(field + ':\\s*(.+)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : 'N/A';
}

const severity   = extractField(rawContent, 'SEVERITY');
const score      = extractField(rawContent, 'SCORE');
const summary    = extractField(rawContent, 'SUMMARY');
const issues     = extractField(rawContent, 'ISSUES');
const suggestion = extractField(rawContent, 'SUGGESTIONS');
const isCritical = severity.toUpperCase().includes('CRITICAL');

let pr = {};
let files = [];
let reviewedIds = [];
try {
  const prev = $node['📝 Build Rich Review Prompt'].json;
  pr = prev.pr || {};
  files = prev.files || [];
  reviewedIds = prev.reviewedIds || [];
} catch(e) {
  console.log('Could not get PR context:', e.message);
}

return [{ json: {
  isCritical,
  severity,
  score,
  summary,
  issues,
  suggestion,
  pr,
  files,
  reviewedIds,
  reviewedAt: new Date().toISOString()
} }];

// Build CRITICAL Teams Adaptive Card + GitHub comment
const d = $input.first().json;
const pr = d.pr || {};

// GitHub markdown comment
const ghComment = [
  '## 🤖 AI Code Review',
  '',
  '| Field | Value |',
  '|---|---|',
  '| **Severity** | 🚨 ' + d.severity + ' |',
  '| **Score** | ' + d.score + '/10 |',
  '| **Author** | @' + pr.author + ' |',
  '| **Branch** | `' + pr.branch + '` → `' + pr.baseBranch + '` |',
  '',
  '### 📋 Summary',
  d.summary,
  '',
  '### ⚠️ Issues',
  '> ' + d.issues,
  '',
  '### 💡 Suggestion',
  d.suggestion,
  '',
  '---',
  '_Reviewed by AI Code Review Agent at ' + d.reviewedAt + '_'
].join('\n');

// Teams Adaptive Card
const teamsCard = {
  type: 'message',
  attachments: [{
    contentType: 'application/vnd.microsoft.card.adaptive',
    content: {
      type: 'AdaptiveCard',
      version: '1.4',
      body: [
        { type: 'TextBlock', text: '🚨 CRITICAL PR DETECTED', size: 'Large', weight: 'Bolder', color: 'Attention' },
        { type: 'FactSet', facts: [
          { title: 'PR', value: '#' + pr.number + ': ' + pr.title },
          { title: 'Author', value: pr.author },
          { title: 'Branch', value: pr.branch + ' → ' + pr.baseBranch },
          { title: 'Score', value: d.score + '/10' }
        ]},
        { type: 'TextBlock', text: '📋 Summary', weight: 'Bolder', spacing: 'Medium' },
        { type: 'TextBlock', text: d.summary, wrap: true },
        { type: 'TextBlock', text: '⚠️ Issues', weight: 'Bolder', spacing: 'Medium', color: 'Attention' },
        { type: 'TextBlock', text: d.issues, wrap: true, color: 'Attention' },
        { type: 'TextBlock', text: '💡 Suggestion', weight: 'Bolder', spacing: 'Medium' },
        { type: 'TextBlock', text: d.suggestion, wrap: true }
      ],
      actions: [{ type: 'Action.OpenUrl', title: '🔍 Review PR Now', url: pr.url }]
    }
  }]
};

return [{ json: {
  ghComment,
  teamsCard: teamsCard,
  prNumber: pr.number,
  prUrl: pr.url,
  pr,
  reviewedIds: d.reviewedIds,
  severity: d.severity,
  score: d.score,
  summary: d.summary,
  issues: d.issues,
  suggestion: d.suggestion,
  reviewedAt: d.reviewedAt
} }];

