const d = $input.first().json;
const pr = d.pr || {};
const reviewedIds = d.reviewedIds || [];

if (pr.number && !reviewedIds.includes(pr.number)) {
  reviewedIds.push(pr.number);
}

const trimmed = reviewedIds.slice(-100);

try {
  const stored = $getWorkflowStaticData('global');
  stored.reviewedPrIds = trimmed;
  stored.lastRunAt = new Date().toISOString();
  stored.totalReviewed = (stored.totalReviewed || 0) + 1;
  console.log('Agent memory saved. Total reviewed:', stored.totalReviewed);
} catch(e) {
  console.log('Memory save failed:', e.message);
}

return [{ json: {
  done: true,
  prNumber: pr.number,
  prTitle: pr.title,
  severity: d.severity,
  score: d.score,
  totalCached: trimmed.length,
  lastRunAt: new Date().toISOString()
} }];
